"""The README derivations are generated by SymPy and must agree with the numeric code."""

from __future__ import annotations

import numpy as np
import pytest
import sympy as sp

from src.math_modeling import merit_indices as mi
from src.math_modeling import symbolic_derivations as sd

PROBLEMS = sd.all_problems()


def _fixed(expr):
    """Substitute design constants (not material symbols) with 1."""
    return expr.subs({sd.L: 1, sd.w: 1, sd.S: 1, sd.F: 1, sd.C1: 1})


@pytest.mark.parametrize("key,expected", [
    ("IM1", sd.rho / sd.E ** sp.Rational(1, 3)),
    ("IM_beam", sd.rho / sp.sqrt(sd.E)),
    ("IM2", sd.rho / sd.sigma_y),
    ("IM3", sd.Cm * sd.rho / sd.E ** sp.Rational(1, 3)),
])
def test_performance_index_is_the_material_group(key, expected):
    assert sp.simplify(PROBLEMS[key].performance_index - expected) == 0


@pytest.mark.parametrize("key", list(PROBLEMS))
def test_optimum_is_geometry_times_index(key):
    p = PROBLEMS[key]
    ratio = sp.simplify(p.optimum / p.performance_index)
    assert not ratio.has(sd.E, sd.rho, sd.sigma_y, sd.Cm)      # geometry/requirement only


def test_symbolic_matches_numeric_indices():
    E, rho, sy, price = 70.0, 2810.0, 503.0, 4.0
    perf = mi.performance_indices(E, rho, sy, price)
    sub = {sd.E: E, sd.rho: rho / 1000.0, sd.sigma_y: sy, sd.Cm: price}
    assert float(PROBLEMS["IM1"].performance_index.subs(sub)) == pytest.approx(float(perf["P1"]))
    assert float(PROBLEMS["IM2"].performance_index.subs(sub)) == pytest.approx(float(perf["P2"]))
    assert float(PROBLEMS["IM_beam"].performance_index.subs(sub)) == pytest.approx(
        1.0 / float(mi.bending_beam_index(E, rho)))


def test_minimising_p_selects_the_same_material_as_maximising_im():
    E = np.array([48.0, 70.0, 3.2, 2.4])
    rho = np.array([1550.0, 2810.0, 1300.0, 1200.0])
    perf = mi.performance_indices(E, rho, np.array([500.0, 503.0, 100.0, 60.0]), np.array([30.0, 4.0, 90.0, 5.0]))
    assert int(np.argmin(perf["P1"])) == int(np.argmax(mi.bending_panel_index(E, rho)))
